#!/usr/bin/env bash
set -Eeuo pipefail
umask 077

# Creates a separate optimized VLESS/XHTTP packet-up inbound in 3x-ui, an nginx origin
# protected with X-CDN-Origin-Secret, and a harmless movie-catalog decoy site.
# Intended for Ubuntu hosts where nginx and 3x-ui/Xray are already installed.

XRAY_BIN="/usr/local/x-ui/bin/xray-linux-amd64"
XRAY_CONFIG="/usr/local/x-ui/bin/config.json"
XUI_DB="/etc/x-ui/x-ui.db"
XUI_PANEL_BIN="/usr/local/x-ui/x-ui"
XUI_PATCH_MARKER="/usr/local/x-ui/.patch-xhttp-2811"
REQUIRED_XUI_PATCH_ID="xhttp-sessionid-extra-external-tls-2811-v3"
NGINX_CONF_DIR="/etc/nginx/conf.d"

die() { printf 'ERROR: %s\n' "$*" >&2; exit 1; }
need() { command -v "$1" >/dev/null 2>&1 || die "Required command is missing: $1"; }

[[ ${EUID:-$(id -u)} -eq 0 ]] || die "Run this script as root."

install_system_dependencies() {
    local packages=()
    command -v nginx >/dev/null 2>&1 || packages+=(nginx)
    command -v python3 >/dev/null 2>&1 || packages+=(python3)
    command -v openssl >/dev/null 2>&1 || packages+=(openssl)
    command -v ss >/dev/null 2>&1 || packages+=(iproute2)
    command -v curl >/dev/null 2>&1 || packages+=(curl)
    command -v certbot >/dev/null 2>&1 || packages+=(certbot)

    if (( ${#packages[@]} > 0 )); then
        command -v apt-get >/dev/null 2>&1 || die "Missing packages: ${packages[*]}; automatic installation requires apt-get"
        printf 'Installing required packages: %s\n' "${packages[*]}"
        export DEBIAN_FRONTEND=noninteractive
        apt-get update
        apt-get install -y --no-install-recommends "${packages[@]}"
    fi
}

install_system_dependencies
for cmd in nginx systemctl python3 openssl ss curl certbot base64 gzip tar find sha256sum sed awk; do need "$cmd"; done
[[ -x "$XUI_PANEL_BIN" ]] || die "3x-ui panel binary not found: $XUI_PANEL_BIN"
[[ -x "$XRAY_BIN" ]] || die "Xray binary not found: $XRAY_BIN"
[[ -f "$XRAY_CONFIG" ]] || die "Xray runtime config not found: $XRAY_CONFIG"
[[ -f "$XUI_DB" ]] || die "3x-ui database not found: $XUI_DB"

verify_combined_xhttp_patch() {
    local marker_patch_id marker_sha current_sha
    [[ -r "$XUI_PATCH_MARKER" ]] || die "Combined XHTTP/External Proxy patch marker not found: $XUI_PATCH_MARKER. Install patch-xhttp-2.8.11.sh first."

    marker_patch_id=$(sed -n 's/^patch_id=//p' "$XUI_PATCH_MARKER" | head -n1)
    [[ "$marker_patch_id" == "$REQUIRED_XUI_PATCH_ID" ]] || die "Required panel patch is not installed (expected $REQUIRED_XUI_PATCH_ID, found ${marker_patch_id:-unknown})."

    marker_sha=$(sed -n 's/^binary_sha256=//p' "$XUI_PATCH_MARKER" | head -n1)
    [[ "$marker_sha" =~ ^[[:xdigit:]]{64}$ ]] || die "Panel patch marker does not contain a valid binary checksum."
    current_sha=$(sha256sum "$XUI_PANEL_BIN" | awk '{print $1}')
    [[ "$current_sha" == "$marker_sha" ]] || die "3x-ui binary no longer matches the combined patch. Reinstall patch-xhttp-2.8.11.sh before continuing."
}

verify_combined_xhttp_patch

systemctl enable --now nginx
systemctl is-active --quiet x-ui || die "x-ui is not active"
nginx -t >/dev/null

read -rp 'Origin domain (for example example.com): ' ORIGIN_DOMAIN
ORIGIN_DOMAIN=${ORIGIN_DOMAIN,,}
[[ "$ORIGIN_DOMAIN" =~ ^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$ ]] || die "Invalid origin domain"

read -rp 'CDN distribution domain (for example cdn.example.com): ' CDN_DOMAIN
CDN_DOMAIN=${CDN_DOMAIN,,}
[[ "$CDN_DOMAIN" =~ ^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$ ]] || die "Invalid CDN domain"
[[ "$ORIGIN_DOMAIN" != "$CDN_DOMAIN" ]] || die "Origin and CDN domains must be different to avoid a proxy loop"

read -rp 'X-CDN-Origin-Secret value [Enter = generate 64-char value]: ' CDN_SECRET
SECRET_GENERATED=0
if [[ -z "$CDN_SECRET" ]]; then
    CDN_SECRET=$(openssl rand -hex 32)
    SECRET_GENERATED=1
fi
[[ ${#CDN_SECRET} -ge 32 ]] || die "The secret must contain at least 32 characters"
[[ "$CDN_SECRET" != *$'\n'* && "$CDN_SECRET" != *$'\r'* ]] || die "The secret must not contain newlines"
[[ "$CDN_SECRET" =~ ^[A-Za-z0-9._~-]+$ ]] || die "Use only letters, digits, dot, underscore, tilde and hyphen in the secret"

DISCOVERY=$(python3 - "$XUI_DB" <<'PY'
import sqlite3, sys
con = sqlite3.connect(sys.argv[1])
values = dict(con.execute("SELECT key, value FROM settings"))
port = values.get("webPort", "2053")
base = values.get("webBasePath", "/").strip()
if not base.startswith("/"):
    base = "/" + base
base = base.rstrip("/")
scheme = "https" if values.get("webCertFile", "").strip() and values.get("webKeyFile", "").strip() else "http"
print(f"{scheme}://127.0.0.1:{port}{base}")
PY
)
read -rp "Local 3x-ui URL [$DISCOVERY]: " XUI_URL
XUI_URL=${XUI_URL:-$DISCOVERY}
XUI_URL=${XUI_URL%/}
read -rp '3x-ui username: ' XUI_USER
read -rp '3x-ui password: ' XUI_PASS
[[ -n "$XUI_USER" && -n "$XUI_PASS" ]] || die "3x-ui credentials are required"

DEPLOY_ID=$(openssl rand -hex 6)
PUBLIC_PATH="/assets-$(openssl rand -hex 12).css"
INTERNAL_PATH="/cdnapi-$(openssl rand -hex 12).txt"
BOT_EXTERNAL_REMARK="bot:{\"path\":\"${PUBLIC_PATH}\",\"host\":\"${CDN_DOMAIN}\"}"
CLIENT_UUID=$(cat /proc/sys/kernel/random/uuid)
INBOUND_TAG="inbound-cdn-${DEPLOY_ID}"
REMARK="CDN movies ${CDN_DOMAIN}"
SITE_DIR="/var/www/cdn-movies-${DEPLOY_ID}"
NGINX_FILE="${NGINX_CONF_DIR}/cdn-movies-${DEPLOY_ID}.conf"
RESULT_DIR="/root/xhttp-cdn-${DEPLOY_ID}"
BACKUP_DIR="/root/xhttp-cdn-backups/$(date -u +%Y%m%dT%H%M%SZ)-${DEPLOY_ID}"
HELPER="/tmp/xui-api-${DEPLOY_ID}.py"
PAYLOAD="/tmp/xui-payload-${DEPLOY_ID}.json"

find_free_port() {
    local candidate random_hex
    for _ in $(seq 1 200); do
        random_hex=$(openssl rand -hex 2)
        candidate=$((20000 + 16#$random_hex % 20000))
        if ! ss -H -ltn "sport = :${candidate}" | grep -q .; then
            printf '%s' "$candidate"
            return 0
        fi
    done
    return 1
}
INBOUND_PORT=$(find_free_port) || die "Could not find a free local port"

mkdir -p "$BACKUP_DIR" "$RESULT_DIR"
chmod 700 "$BACKUP_DIR" "$RESULT_DIR"
cp -a "$XRAY_CONFIG" "$BACKUP_DIR/config.json"
cp -a /etc/nginx/nginx.conf "$BACKUP_DIR/nginx.conf"
cp -a "$NGINX_CONF_DIR" "$BACKUP_DIR/conf.d"
python3 - "$XUI_DB" "$BACKUP_DIR/x-ui.db" <<'PY'
import sqlite3, sys
with sqlite3.connect(sys.argv[1]) as source, sqlite3.connect(sys.argv[2]) as target:
    source.backup(target)
PY

install -m 700 /dev/stdin "$HELPER" <<'PY'
#!/usr/bin/env python3
import http.cookiejar, json, ssl, sys, urllib.parse, urllib.request

action, base = sys.argv[1], sys.argv[2].rstrip("/")
with open("/dev/fd/3", encoding="utf-8") as auth:
    username = auth.readline().rstrip("\n")
    password = auth.readline().rstrip("\n")

cookies = http.cookiejar.CookieJar()
context = ssl._create_unverified_context()  # Local loopback panel; avoids SNI mismatch.
opener = urllib.request.build_opener(
    urllib.request.HTTPSHandler(context=context),
    urllib.request.HTTPCookieProcessor(cookies),
)

def call(path, data=None):
    encoded = None if data is None else urllib.parse.urlencode(data).encode()
    with opener.open(base + path, encoded, timeout=30) as response:
        result = json.load(response)
    if not result.get("success"):
        raise SystemExit(result.get("msg") or repr(result))
    return result.get("obj")

call("/login", {"username": username, "password": password})

if action == "add":
    with open(sys.argv[3], encoding="utf-8") as handle:
        payload = json.load(handle)
    call("/panel/api/inbounds/add", payload)
    items = call("/panel/api/inbounds/list") or []
    matches = [item for item in items if int(item.get("port", -1)) == int(payload["port"])]
    if len(matches) != 1:
        raise SystemExit("Inbound was added but could not be uniquely verified through 3x-ui")
    print(matches[0]["id"])
elif action == "delete":
    call("/panel/api/inbounds/del/" + sys.argv[3], {})
else:
    raise SystemExit("Unknown action")
PY

python3 - "$PAYLOAD" "$INBOUND_PORT" "$CLIENT_UUID" "$INTERNAL_PATH" "$INBOUND_TAG" "$REMARK" "$CDN_DOMAIN" "$BOT_EXTERNAL_REMARK" <<'PY'
import json, sys
out, port, uuid, path, tag, remark, cdn_domain, external_remark = sys.argv[1:]
xhttp = {
    "headers": {"User-Agent": "golang"},
    "host": "",
    "mode": "packet-up",
    "path": path,
    "serverMaxHeaderBytes": 32768,
    "scMaxEachPostBytes": "1048576",
    "scMinPostsIntervalMs": "10-20",
    "scMaxBufferedPosts": 30,
    "scStreamUpServerSecs": "20-80",
    "uplinkDataPlacement": "body",
    "uplinkHTTPMethod": "GET",
    "sessionIDPlacement": "query",
    "sessionIDKey": "auth",
    "sessionIDTable": "Base62",
    "sessionIDLength": "16-32",
    "seqPlacement": "query",
    "seqKey": "chunk_id",
    "xPaddingBytes": "50-150",
    "xPaddingPlacement": "header",
    "xPaddingKey": "X-Padding",
    "xPaddingMethod": "tokenish",
    "xPaddingObfsMode": True,
    "noSSEHeader": True,
    "noGRPCHeader": True,
    "xmux": {
        "maxConcurrency": "0",
        "maxConnections": "2-4",
        "cMaxReuseTimes": "1000",
        "hMaxRequestTimes": "600-900",
        "hMaxReusableSecs": "100",
        "hKeepAlivePeriod": 20000,
    },
    "enableXmux": True,
}
settings = {
    "clients": [{
        "id": uuid, "flow": "", "email": remark,
        "limitIp": 0, "totalGB": 0, "expiryTime": 0, "enable": True,
        "tgId": "", "subId": "", "reset": 0,
    }],
    "decryption": "none",
    "fallbacks": [],
}
external_proxy = [{
    "forceTls": "tls",
    "dest": cdn_domain,
    "port": 443,
    "remark": external_remark,
}]
stream = {
    "network": "xhttp",
    "security": "none",
    "externalProxy": external_proxy,
    "xhttpSettings": xhttp,
}
sniffing = {
    "enabled": True,
    "destOverride": ["http", "tls", "quic", "fakedns"],
    "metadataOnly": False,
    "routeOnly": True,
}
payload = {
    "up": 0, "down": 0, "total": 0, "allTime": 0,
    "remark": remark, "enable": "true", "expiryTime": 0,
    "listen": "127.0.0.1", "port": int(port), "protocol": "vless",
    "settings": json.dumps(settings, separators=(",", ":")),
    "streamSettings": json.dumps(stream, separators=(",", ":")),
    "tag": tag,
    "sniffing": json.dumps(sniffing, separators=(",", ":")),
}
with open(out, "w", encoding="utf-8") as handle:
    json.dump(payload, handle)
PY
chmod 600 "$PAYLOAD"

mkdir -p "$SITE_DIR/static"
chmod 755 "$SITE_DIR" "$SITE_DIR/static"
install -m 644 /dev/stdin "$SITE_DIR/index.html" <<EOF
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>CineScope — Watch something great</title>
  <meta name="description" content="A curated catalog of films, premieres and timeless favorites.">
  <link rel="stylesheet" href="/static/app.css">
</head>
<body>
  <header><div class="logo">CINE<span>SCOPE</span></div><nav>Home &nbsp; Movies &nbsp; Series &nbsp; Collections</nav></header>
  <main>
    <section class="hero"><div><p class="eyebrow">FEATURED TONIGHT</p><h1>Beyond the Horizon</h1><p>A quiet journey through distant cities, unexpected friendships and one unforgettable summer.</p><button>▶ Watch trailer</button></div></section>
    <section><h2>Trending now</h2><div class="grid">
      <article class="c1"><b>Midnight Signal</b><small>Thriller · 2026</small></article>
      <article class="c2"><b>Atlas of Rain</b><small>Drama · 2025</small></article>
