EOF

install -m 644 /dev/stdin "$SITE_DIR/static/app.css" <<'EOF'
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,sans-serif;background:#080a0f;color:#f5f6f8}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% 0,#251d46 0,transparent 35%),#080a0f}header{height:72px;display:flex;align-items:center;justify-content:space-between;padding:0 6vw;border-bottom:1px solid #ffffff17;background:#080a0fcc;backdrop-filter:blur(16px)}.logo{font-weight:900;letter-spacing:.12em;font-size:20px}.logo span,.eyebrow{color:#ff3c68}nav{font-size:14px;color:#bbc0cd}main{max-width:1180px;margin:auto;padding:36px 24px 70px}.hero{min-height:430px;border-radius:24px;padding:65px;display:flex;align-items:end;background:linear-gradient(90deg,#080a0fee 10%,#080a0f35),radial-gradient(circle at 80% 28%,#ef476f 0,#683a75 25%,#14213d 65%);box-shadow:0 30px 80px #0008}.hero div{max-width:590px}.eyebrow{font-size:12px;font-weight:800;letter-spacing:.18em}.hero h1{font-size:58px;line-height:1;margin:12px 0}.hero p{color:#d5d8df;line-height:1.65}.hero button{border:0;border-radius:999px;padding:13px 20px;background:#fff;color:#10131b;font-weight:800;margin-top:12px}h2{margin:42px 0 18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.grid article{height:190px;border-radius:18px;padding:20px;display:flex;flex-direction:column;justify-content:end;background-size:cover;box-shadow:inset 0 -100px 80px #000b}.grid b{font-size:20px}.grid small{color:#c9cbd2;margin-top:6px}.c1{background:linear-gradient(135deg,#182848,#4b6cb7)}.c2{background:linear-gradient(135deg,#134e5e,#71b280)}.c3{background:linear-gradient(135deg,#8e2de2,#4a00e0)}.c4{background:linear-gradient(135deg,#ee9ca7,#ffdde1)}.c5{background:linear-gradient(135deg,#c79081,#dfa579)}.c6{background:linear-gradient(135deg,#654ea3,#eaafc8)}footer{text-align:center;color:#737887;border-top:1px solid #ffffff12;padding:28px}@media(max-width:760px){nav{display:none}.hero{min-height:380px;padding:32px}.hero h1{font-size:40px}.grid{grid-template-columns:1fr 1fr}}@media(max-width:470px){.grid{grid-template-columns:1fr}}
EOF

CERT_DIR="/etc/letsencrypt/live/${ORIGIN_DOMAIN}"
if [[ ! -r "$CERT_DIR/fullchain.pem" || ! -r "$CERT_DIR/privkey.pem" ]]; then
    printf "No origin certificate found; requesting Let's Encrypt for %s...\n" "$ORIGIN_DOMAIN"
    mkdir -p "$SITE_DIR/.well-known/acme-challenge"
    install -m 640 -o root -g www-data /dev/stdin "$NGINX_FILE" <<EOF
server {
    listen 80;
    listen [::]:80;
    server_name ${ORIGIN_DOMAIN};
    root ${SITE_DIR};
    location ^~ /.well-known/acme-challenge/ { try_files \$uri =404; }
    location / { try_files \$uri \$uri/ =404; }
}
EOF
    nginx -t
    systemctl reload nginx
    certbot certonly --webroot --webroot-path "$SITE_DIR" \
        --non-interactive --agree-tos --register-unsafely-without-email \
        --domain "$ORIGIN_DOMAIN"
fi
[[ -r "$CERT_DIR/fullchain.pem" && -r "$CERT_DIR/privkey.pem" ]] || die "Origin TLS certificate is unavailable"
TLS_BLOCK=$(printf '    listen 443 ssl http2;\n    listen [::]:443 ssl http2;\n    ssl_certificate %s/fullchain.pem;\n    ssl_certificate_key %s/privkey.pem;\n' "$CERT_DIR" "$CERT_DIR")
ORIGIN_SCHEME="https"
ORIGIN_PORT="443"

install -m 640 -o root -g www-data /dev/stdin "$NGINX_FILE" <<EOF
server {
    listen 80;
    listen [::]:80;
${TLS_BLOCK}    server_name ${ORIGIN_DOMAIN};
    root ${SITE_DIR};
    index index.html;

    server_tokens off;
    client_header_buffer_size 16k;
    large_client_header_buffers 16 32k;

    location = ${PUBLIC_PATH} {
        set \$xhttp_method_${DEPLOY_ID} \$request_method;
        if (\$request_method = OPTIONS) { set \$xhttp_method_${DEPLOY_ID} POST; }
        if (\$http_x_cdn_origin_secret != "${CDN_SECRET}") { return 403; }

        proxy_pass http://127.0.0.1:${INBOUND_PORT}${INTERNAL_PATH};
        proxy_method \$xhttp_method_${DEPLOY_ID};
        proxy_http_version 1.1;
        proxy_pass_request_headers on;
        proxy_set_header Host \$host;
        proxy_set_header Connection "";
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-CDN-Origin-Secret "";
        proxy_request_buffering off;
        proxy_buffering off;
        proxy_cache off;
        gzip off;
        proxy_connect_timeout 10s;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
        add_header Cache-Control "no-store" always;
        add_header X-Accel-Buffering "no" always;
    }

    location ~* \.css$ {
        try_files \$uri =404;
        access_log off;
    }

    error_page 404 /404.html;
    location = /404.html { internal; }

    location / {
        try_files \$uri \$uri/ =404;
        add_header Cache-Control "no-cache";
    }
}
EOF

INBOUND_ID=""
COMMITTED=0
cleanup() {
    local exit_code=$?
    if [[ $exit_code -ne 0 && $COMMITTED -eq 0 ]]; then
        printf 'Installation failed; rolling back created objects...\n' >&2
        if [[ -n "$INBOUND_ID" ]]; then
            python3 "$HELPER" delete "$XUI_URL" "$INBOUND_ID" 3<<<"${XUI_USER}"$'\n'"${XUI_PASS}"$'\n' >/dev/null 2>&1 || true
        fi
        rm -f "$NGINX_FILE"
        rm -rf --one-file-system "$SITE_DIR"
        nginx -t >/dev/null 2>&1 && systemctl reload nginx >/dev/null 2>&1 || true
    fi
    rm -f "$HELPER" "$PAYLOAD"
    XUI_PASS=""
    CDN_SECRET=""
    trap - EXIT
    exit "$exit_code"
}
trap cleanup EXIT

# Validate nginx before touching 3x-ui. A proxy target need not be listening for nginx -t.
nginx -t >/dev/null

INBOUND_ID=$(python3 "$HELPER" add "$XUI_URL" "$PAYLOAD" 3<<<"${XUI_USER}"$'\n'"${XUI_PASS}"$'\n')
[[ "$INBOUND_ID" =~ ^[0-9]+$ ]] || die "Unexpected inbound ID returned by 3x-ui: $INBOUND_ID"

for _ in $(seq 1 30); do
    if ss -H -ltn "sport = :${INBOUND_PORT}" | grep -q "127.0.0.1:${INBOUND_PORT}"; then
        break
    fi
    sleep 0.2
done
ss -H -ltn "sport = :${INBOUND_PORT}" | grep -q "127.0.0.1:${INBOUND_PORT}" || die "The new Xray inbound is not listening"

nginx -t >/dev/null
systemctl reload nginx

# Build client JSON and VLESS URL. The origin secret is deliberately not included.
python3 - "$RESULT_DIR" "$CDN_DOMAIN" "$PUBLIC_PATH" "$CLIENT_UUID" "$INBOUND_PORT" "$INTERNAL_PATH" "$INBOUND_ID" <<'PY'
import json, pathlib, sys, urllib.parse
out, domain, public_path, uuid, port, internal_path, inbound_id = sys.argv[1:]
out = pathlib.Path(out)
xhttp = {
    "headers": {"User-Agent": "golang"},
    "host": domain, "mode": "packet-up", "path": public_path,
    "serverMaxHeaderBytes": 32768,
    "scMaxEachPostBytes": "1048576", "scMinPostsIntervalMs": "10-20",
    "scMaxBufferedPosts": 30,
    "uplinkDataPlacement": "body", "uplinkHTTPMethod": "GET",
    "sessionIDPlacement": "query", "sessionIDKey": "auth",
    "sessionIDTable": "Base62", "sessionIDLength": "16-32",
    "seqPlacement": "query", "seqKey": "chunk_id",
    "xPaddingBytes": "50-150", "xPaddingPlacement": "header",
    "xPaddingKey": "X-Padding", "xPaddingMethod": "tokenish",
    "xPaddingObfsMode": True, "noSSEHeader": True, "noGRPCHeader": True,
    "xmux": {"maxConcurrency": "0", "maxConnections": "2-4", "cMaxReuseTimes": "1000", "hMaxRequestTimes": "600-900", "hMaxReusableSecs": "100", "hKeepAlivePeriod": 20000},
    "enableXmux": True,
}
extra = {key: value for key, value in xhttp.items() if key not in {"host", "path", "mode"}}
query = {
    "encryption": "none", "security": "tls", "sni": domain,
    "fp": "chrome", "alpn": "h2", "type": "xhttp",
    "host": domain, "path": public_path, "mode": "packet-up",
    "extra": json.dumps(extra, separators=(",", ":")),
}
link = "vless://" + uuid + "@" + domain + ":443?" + urllib.parse.urlencode(
    query, quote_via=urllib.parse.quote
) + "#" + urllib.parse.quote("CDN-XHTTP-fast")
(out / "client-xhttpSettings.json").write_text(json.dumps(xhttp, indent=2), encoding="utf-8")
(out / "client-extra.json").write_text(json.dumps(extra, indent=2), encoding="utf-8")
(out / "vless-link.txt").write_text(link + "\n", encoding="utf-8")
receipt = {
    "domain": domain, "publicPath": public_path, "internalPath": internal_path,
    "uuid": uuid, "inboundPort": int(port), "xuiInboundId": int(inbound_id),
    "profile": "packet-up-xmux-optimized", "scMaxEachPostBytes": 1048576,
    "scMaxBufferedPosts": 30, "xmuxMaxConnections": "2-4",
    "externalProxyRemark": "bot:" + json.dumps(
        {"path": public_path, "host": domain}, separators=(",", ":")
    ),
}
(out / "deployment.json").write_text(json.dumps(receipt, indent=2), encoding="utf-8")
PY

install -m 700 /dev/stdin "$RESULT_DIR/remove.sh" <<EOF
#!/usr/bin/env bash
set -Eeuo pipefail
[[ \${EUID:-\$(id -u)} -eq 0 ]] || { echo 'Run as root' >&2; exit 1; }
read -rp '3x-ui username: ' XUI_USER
read -rp '3x-ui password: ' XUI_PASS
python3 ${HELPER} delete '${XUI_URL}' '${INBOUND_ID}' 3<<<"\${XUI_USER}"\$'\\n'"\${XUI_PASS}"\$'\\n'
rm -f '${NGINX_FILE}'
rm -rf --one-file-system '${SITE_DIR}'
nginx -t && systemctl reload nginx
echo 'Inbound, nginx vhost and decoy site removed.'
EOF

# Preserve a credential-free API helper so remove.sh remains usable.
cp "$HELPER" "$RESULT_DIR/xui-api.py"
sed -i "s#python3 ${HELPER}#python3 ${RESULT_DIR}/xui-api.py#" "$RESULT_DIR/remove.sh"
chmod 700 "$RESULT_DIR/xui-api.py"

COMMITTED=1

UPGRADE_TMP=$(mktemp)
base64 -d <<'MOVIE_UPGRADE_GZ_BASE64' | gzip -dc > "$UPGRADE_TMP"

MOVIE_UPGRADE_GZ_BASE64
chmod 700 "$UPGRADE_TMP"
bash "$UPGRADE_TMP" "$SITE_DIR"
rm -f "$UPGRADE_TMP"

printf '\nInstallation completed.\n'
printf 'CDN domain:       %s\n' "$CDN_DOMAIN"
printf 'Origin endpoint:  %s://%s:%s\n' "$ORIGIN_SCHEME" "$ORIGIN_DOMAIN" "$ORIGIN_PORT"
if [[ $SECRET_GENERATED -eq 1 ]]; then
    printf 'Required header:  X-CDN-Origin-Secret: %s\n' "$CDN_SECRET"
else
    printf 'Required header:  X-CDN-Origin-Secret: <the value entered during installation>\n'
fi
printf 'Public XHTTP path:%s\n' "$PUBLIC_PATH"
printf 'Internal path:    %s\n' "$INTERNAL_PATH"
printf 'External Proxy:   TLS %s:443\n' "$CDN_DOMAIN"
printf 'Bot metadata:     %s\n' "$BOT_EXTERNAL_REMARK"
printf 'Local inbound:    127.0.0.1:%s\n' "$INBOUND_PORT"
printf '3x-ui inbound ID: %s\n' "$INBOUND_ID"
printf 'Client files:     %s\n' "$RESULT_DIR"
printf 'VLESS link:\n'
cat "$RESULT_DIR/vless-link.txt"
printf '\nTimeweb CDN settings:\n'
printf '  Source:             %s:443 (HTTPS enabled)\n' "$ORIGIN_DOMAIN"
printf '  Distribution:       %s\n' "$CDN_DOMAIN"
printf '  Required header:    X-CDN-Origin-Secret (value printed above)\n'
printf '  Required methods:   GET, HEAD, OPTIONS\n'
printf '  Cache for XHTTP:    disabled/no-store\n'
printf '  Public XHTTP path:  %s\n' "$PUBLIC_PATH"
